import asyncio
from google import genai
from google.genai import types

# Yeu cau google-genai >= 3.2.0 (SDK google-generativeai cu da deprecated)
client = genai.Client()

async def run_voice_hotline_session(pcm_input_chunks):
    # Khai bao tool tra cuu CRM bat dong bo (NON_BLOCKING bat buoc cho Live Extended Thinking)
    check_crm_tool = types.Tool(function_declarations=[{
        "name": "lookup_unit_availability",
        "description": "Tra cuu tinh trang can ho hoac lich hen bac si trong CRM",
        "behavior": "NON_BLOCKING",
        "parameters": {
            "type": "OBJECT",
            "properties": {"code": {"type": "STRING"}},
            "required": ["code"]
        }
    }])

    config = types.LiveConnectConfig(
        response_modalities=[types.Modality.AUDIO],
        thinking_config=types.ThinkingConfig(thinking_level="low"),
        output_audio_transcription=types.AudioTranscriptionConfig(),
        context_window_compression=types.ContextWindowCompressionConfig(
            sliding_window=types.SlidingWindow()
        ),
        tools=[check_crm_tool],
        system_instruction=types.Content(parts=[types.Part(
            text="Ban la tro ly tong dai DOMATION. Noi ngan gon, than thien, khong ngat quang."
        )])
    )

    async with client.aio.live.connect(
        model="gemini-3.8-live-extended-thinking", config=config
    ) as session:
        for chunk in pcm_input_chunks:
            # Bat buoc dung key audio= (khong dung media= da cu)
            await session.send_realtime_input(
                audio=types.Blob(data=chunk, mime_type="audio/pcm;rate=16000")
            )
        await session.send_realtime_input(audio_stream_end=True)

        async for msg in session.receive():
            sc = msg.server_content
            if sc and sc.model_turn:
                for part in sc.model_turn.parts:
                    if part.inline_data:
                        # Phat audio PCM 24kHz ve WebRTC/SIP gateway
                        _play_pcm_24khz(part.inline_data.data)
            if sc and sc.output_transcription:
                print("[Transcript]", sc.output_transcription.text)
            if sc and sc.interrupted:
                _flush_audio_buffer()
            if getattr(msg, "interaction_status", None) == "IDLE":
                break

def generate_vertical_ad_from_reference(product_img_path: str):
    # Upload anh tham chieu qua Files API va cho ACTIVE truoc khi goi Interactions API
    uploaded = client.files.upload(file=product_img_path)
    interaction = client.interactions.create(
        model="gemini-omni-1.2-flash",
        input=[
            {"type": "text", "text": (
                "Quay video quang cao 9:16 dai 10 giay o 720p gioi thieu san pham trong anh tham chieu, "
                "anh sang studio sang trong, chuyen dong camera tinh te va nhac nen hien dai."
            )},
            {"type": "image", "uri": uploaded.uri, "mime_type": uploaded.mime_type}
        ],
        generation_config={"aspect_ratio": "9:16", "resolution": "720p", "duration_seconds": 10}
    )
    return interaction.id, interaction.output_video
